-- ==============================================================
-- BLOC Z — Vérification finale
-- =============================================================
SET ROLE postgres;
SELECT 'tenants' AS tbl, count(*) FROM public.tenants
UNION ALL SELECT 'users', count(*) FROM public.users
UNION ALL SELECT 'clients', count(*) FROM public.clients
UNION ALL SELECT 'cases', count(*) FROM public.cases
UNION ALL SELECT 'tasks', count(*) FROM public.tasks
UNION ALL SELECT 'documents', count(*) FROM public.documents
UNION ALL SELECT 'invoices', count(*) FROM public.invoices
UNION ALL SELECT 'events', count(*) FROM public.events
UNION ALL SELECT 'event_assignments', count(*) FROM public.event_assignments
UNION ALL SELECT 'messages', count(*) FROM public.messages
UNION ALL SELECT 'notifications', count(*) FROM public.notifications
UNION ALL SELECT 'currencies', count(*) FROM public.currencies
UNION ALL SELECT 'auth_users', count(*) FROM auth.users WHERE id LIKE 'b1%'
ORDER BY tbl;